insert into public.course_sources (id, provider, title, url, kind, entry_year, note) values
  ('usyd-2027', 'The University of Sydney', 'Admission guide for domestic students applying for 2027 entry', 'https://www.sydney.edu.au/content/dam/corporate/documents/study/guides/admission-guide-domestic-stduents-applying-for-2027-entry-.pdf', 'indicative', 2027, 'Indicative selection ranks based on the previous year''s entry; not guaranteed. Prerequisite and assumed-knowledge subjects are NSW HSC subjects.'),
  ('monash-2027', 'Monash University', 'Monash Guarantee ATARs, 2027 entry', 'https://www.monash.edu/study/how-to-apply/entry-requirements/entry-schemes/the-monash-guarantee/monash-guarantee-atars', 'guaranteed', 2027, 'Meet this ATAR (including adjustments) and the course prerequisites to be guaranteed an offer. RC = range of criteria (extra requirements such as a personal statement, interview or audition). Check VCE prerequisites on each course page.'),
  ('deakin', 'Deakin University', 'Find a course by ATAR', 'https://www.deakin.edu.au/study/find-a-course-by-atar', 'published', null, 'ATARs as published by Deakin; the page doesn''t say which intake or whether they are guaranteed or lowest selection ranks.'),
  ('uq-2027', 'The University of Queensland', 'ATAR guarantee, Semester 1 2027', 'https://study.uq.edu.au/admissions/undergraduate/review-entry-requirements/guaranteed-atar', 'guaranteed', 2027, 'Guaranteed thresholds include adjustments; the program must be your first QTAC preference. Final January cut-offs are usually lower. Check prerequisites on each program page.'),
  ('qut-2027', 'Queensland University of Technology', 'Guaranteed course offers, 2027', 'https://www.qut.edu.au/study/applying/guaranteed-course-offers', 'guaranteed', 2027, 'Offer guarantee applies to Semester 1 rounds up to the main January round; you must meet all other course requirements. Check prerequisites on each course page.'),
  ('curtin-nursing', 'Curtin University', 'Bachelor of Science (Nursing) course page', 'https://www.curtin.edu.au/study/offering/course-ug-bachelor-of-science-nursing--b-nurs', 'minimum', null, 'Minimum ATAR; meeting it doesn''t guarantee selection. The page notes the Nursing stream is replaced by Advanced Nursing from 2026.'),
  ('curtin-engineering', 'Curtin University', 'Bachelor of Engineering (Honours) course page', 'https://www.curtin.edu.au/study/offering/course-ug-bachelor-of-engineering-honours--bh-engr/?nocache=1', 'guaranteed', null, 'Guaranteed ATAR or equivalent shown on the course page; year not stated.'),
  ('tisc-2026', 'Tertiary Institutions Service Centre (WA)', '2026 Admission Requirements for School Leavers', 'https://hedlandshs.wa.edu.au/wp-content/uploads/2024/04/TISC-2026.pdf', 'prerequisites', 2026, 'WA prerequisite (scaled score of 50+) and recommended ATAR courses. About 70 is the minimum entry at most WA universities; check each course page for its ATAR.');
