insert into public.tafe_courses (qualification_id, provider, state, course, offered_code, apprenticeship, requirements, url) values
  ('UEE30820', 'TAFE NSW', 'NSW', 'Certificate III in Electrotechnology Electrician', 'UEE30820', true, array['Apprenticeship: employed as an apprentice; ACAP submits Training Proposal Plan.', 'Non-apprentice: 21+, 2 years'' work experience in the trade, currently employed in the industry.', 'Recommended LLN Year 10; may require LLN test.', 'Recommended: work at heights; distinguish colours.']::text[], 'https://www.tafensw.edu.au/course-areas/electrotechnology/courses/certificate-iii-in-electrotechnology-electrician--UEE30820-01'),
  ('CPC32420', 'TAFE NSW', 'NSW', 'Certificate III in Plumbing', 'CPC32420', true, array['Apprenticeship: employed as an apprentice; register with ACAP.', 'Non-apprentice: 21+, 2 years'' work experience, currently employed in industry.', 'White card (general construction induction) needed before going on a construction site.']::text[], 'https://www.tafensw.edu.au/course-areas/building-and-construction-trades/courses/certificate-iii-in-plumbing-general-plumber--CPC32420-01'),
  ('CPC30220', 'TAFE NSW', 'NSW', 'Certificate III in Carpentry', 'CPC30220', true, array['Apprenticeship: employed as an apprentice; ACAP submits TPP.', 'Non-apprentice: RPL; 21+; 2 years'' experience; currently employed.', 'Recommended LLN Year 10; may require LLN test.']::text[], 'https://www.tafensw.edu.au/course-areas/building-and-construction-trades/courses/certificate-iii-in-carpentry--CPC30220-01'),
  ('AUR30620', 'TAFE NSW', 'NSW', 'Certificate III in Light Vehicle Mechanical Technology', 'AUR30620', true, array['Apprenticeship: employed as an apprentice; ACAP submits TPP.', 'Non-apprentice: 21+; working in industry or 2 years'' experience.', 'Must complete an LLND test before starting (minimum scores in digital literacy, learning, reading, writing, oral communication and numeracy).']::text[], 'https://www.tafensw.edu.au/course-areas/automotive/courses/certificate-iii-in-light-vehicle-mechanical-technology--AUR30620-01'),
  ('UEE32220', 'TAFE NSW', 'NSW', 'Certificate III in Air-conditioning and Refrigeration', 'UEE32220', true, array['Apprenticeship: employed as an apprentice; register with ACAP.', 'Non-apprentice: 21+, 2 years'' experience, currently employed.', 'Reading, writing and maths at Year 10 or equivalent.', 'Refrigerant Handling Licence evidence during the course.']::text[], 'https://www.tafensw.edu.au/course-areas/AUTO/courses/AUTO--UEE32220-01'),
  ('MEM30219', 'TAFE NSW', 'NSW', 'Certificate III in Engineering – Mechanical Trade', 'MEM30219', true, array['Apprenticeship: employed as an apprentice; submit TPP.', 'Recommended LLN Year 10/12; may require LLN test.', 'Recommended: School Certificate or equivalent; white card may be needed.']::text[], 'https://www.tafensw.edu.au/course-areas/engineering/courses/certificate-iii-in-engineering-mechanical-trade-fitting--MEM30219-04'),
  ('MEM30319', 'TAFE NSW', 'NSW', 'Certificate III in Engineering – Fabrication Trade', 'MEM31922', true, array['Apprenticeship: employed as an apprentice with employer letter; submit TPP.', 'Recommended LLN Year 10.', 'TAFE NSW enrols this trade under code MEM31922; check the TAFE page for the current release.']::text[], 'https://www.tafensw.edu.au/course-areas/engineering/courses/engineering--MEM31922-06'),
  ('SIT30821', 'TAFE NSW', 'NSW', 'Certificate III in Commercial Cookery', 'SIT30821', true, array['Apprenticeship: employed as an apprentice; register with ACAP.', 'Non-apprentice: no entry requirements stated.', 'Recommended LLN Year 10; may require LLN test.', 'Supply own chef''s uniform and toolkit.']::text[], 'https://www.tafensw.edu.au/course-areas/food-and-hospitality/courses/certificate-iii-in-commercial-cookery--SIT30821-01'),
  ('SIT40521', 'TAFE NSW', 'NSW', 'Certificate IV in Kitchen Management', 'SIT40521', false, array['Evidence of previous experience or study required.', 'Apprenticeship or non-apprenticeship.', 'LLN skills test.', 'Equipment about $350–$420 (uniform and chef''s toolbox).']::text[], 'https://www.tafensw.edu.au/course-areas/food-and-hospitality/courses/certificate-iv-in-kitchen-management--SIT40521-01'),
  ('SHB30416', 'TAFE NSW', 'NSW', 'Certificate III in Hairdressing', 'SHB30416', true, array['Apprenticeship: employed as an apprentice; register with ACAP.', 'Non-apprentice: 21+, 2 years'' experience, currently employed (RPL plus gap training).', 'No prerequisite courses.']::text[], 'https://tafensw.edu.au/course-areas/hair-and-beauty/courses/certificate-iii-in-hairdressing--SHB30416-01'),
  ('CHC33021', 'TAFE NSW', 'NSW', 'Certificate III in Individual Support', 'CHC33021', false, array['No entry requirements (or as a traineeship if employed as a trainee).', 'During study: National Police Check, NDIS Worker Check, Working with Children Check, vaccinations (may include COVID-19, hepatitis A and B, influenza). 120 hours'' work placement.']::text[], 'https://www.tafensw.edu.au/course-areas/healthcare/courses/certificate-iii-in-individual-support-ageing-and-disability--CHC33021-04'),
  ('CHC43121', 'TAFE NSW', 'NSW', 'Certificate IV in Disability Support', 'CHC43121', false, array['Must have completed Certificate III in Individual Support (Disability) (CHC33021 or CHC33015), or CHC30408 plus the entry skill set.', 'During study: Working with Children Check, National Police Check, NDIS Worker Screening Check, vaccinations and health screening.']::text[], 'https://www.tafensw.edu.au/course-areas/healthcare/courses/certificate-iv-in-disability-support--CHC43121-01'),
  ('HLT33115', 'TAFE NSW', 'NSW', 'Certificate III in Health Services Assistance', 'HLT33115', false, array['No entry requirements; Year 10 LLN recommended.', 'During study: Working with Children Check, National Police Check, NDIS Worker Check, vaccinations and health screening.', 'Minimum 80 hours'' work placement.', 'Must be able to perform 2 minutes of CPR at floor level.']::text[], 'https://www.tafensw.edu.au/course-areas/healthcare/courses/certificate-iii-in-health-services-assistance-assisting-in-nursing-work-in-acute-care--HLT33115-03'),
  ('HLT35021', 'TAFE NSW', 'NSW', 'Certificate III in Dental Assisting', 'HLT35021', false, array['No entry requirements; LLN test may be required. 350-hour work placement.', 'During study: National Police Check, Working with Children Check, vaccinations and health screening.', 'Must perform 2 minutes of CPR at floor level.']::text[], 'https://www.tafensw.edu.au/course-areas/healthcare/courses/certificate-iii-in-dental-assisting--HLT35021-01'),
  ('HLT54121', 'TAFE NSW', 'NSW', 'Diploma of Nursing', 'HLT54121', false, array['HSC or Year 12 equivalent, or a Certificate III or above.', 'Pre-entry BKSB literacy and numeracy assessment at Exit Level 3+ in English and maths.', 'Must meet the Nursing and Midwifery Board of Australia English language standard.', 'During study: National Police Check, Working with Children Check, vaccinations and health screening.']::text[], 'https://www.tafensw.edu.au/course-areas/healthcare/courses/diploma-of-nursing--HLT54121-01'),
  ('CHC30121', 'TAFE NSW', 'NSW', 'Certificate III in Early Childhood Education and Care', 'CHC30121', false, array['No prior qualification needed; ability to read, write and speak English.', 'Working with Children Check to complete. 160 hours'' work placement.', 'Can be done as a traineeship.', 'Fitness to deliver first aid.']::text[], 'https://www.tafensw.edu.au/course-areas/education-and-training/courses/education-and-training--CHC30121-01'),
  ('CHC50121', 'TAFE NSW', 'NSW', 'Diploma of Early Childhood Education and Care', 'CHC50121', false, array['Must have completed Certificate III in Early Childhood Education and Care (CHC30121 or CHC30113).', 'Year 12 LLN recommended. 280 hours'' work placement.', 'Working with Children Check; vaccinations and health screening.', 'Can be done as a traineeship.']::text[], 'https://tafensw.edu.au/course-areas/healthcare/courses/healthcare--CHC50121-01'),
  ('CHC52021', 'TAFE NSW', 'NSW', 'Diploma of Community Services', 'CHC52021', false, array['Evidence of previous experience or study required (industry experience or community services study ideally).', 'During study: Working with Children Check, National Police Check, NDIS Check, vaccinations and health screening.', 'Minimum 200 hours'' work placement.', 'Can be a traineeship.']::text[], 'https://www.tafensw.edu.au/course-areas/healthcare/courses/diploma-of-community-services--CHC52021-01'),
  ('CHC51015', 'TAFE NSW', 'NSW', 'Diploma of Counselling', 'CHC51015', false, array['Evidence of previous experience or study required; some delivery options have extra entry requirements.', 'Community services experience useful but not essential.']::text[], 'https://www.tafensw.edu.au/course-areas/healthcare/courses/diploma-of-counselling--CHC51015-01'),
  ('ICT50220', 'TAFE NSW', 'NSW', 'Diploma of Information Technology', 'ICT50220', false, array['No additional entry requirements listed for this offering (Database and Data Management specialisation, 6 months full time at St George).']::text[], 'https://www.tafensw.edu.au/course-areas/information-and-communication-technology/courses/diploma-of-information-technology-database-and-data-management--ICT50220-02/offerings/ICT50220-02V02-26SGR-007'),
  ('22603VIC', 'TAFE NSW', 'NSW', 'Certificate IV in Cyber Security', '22603VIC', false, array['Certificate III or higher in IT with networking proficiency, or equivalent industry experience (operating systems, Linux and Windows command line, networking protocols, router and switch configuration).', 'Year 10 LLN; LLN test may be required.']::text[], 'https://www.tafensw.edu.au/course-areas/information-and-communication-technology/courses/certificate-iv-in-cyber-security--22603VIC-01'),
  ('BSB30120', 'TAFE NSW', 'NSW', 'Certificate III in Business', 'BSB30120', false, array['No entry requirements.', 'Year 10 LLN, computer with internet and basic Microsoft Office skills recommended.']::text[], 'https://www.tafensw.edu.au/course-areas/business-and-marketing/courses/certificate-iii-in-business--BSB30120-01'),
  ('FNS50222', 'TAFE NSW', 'NSW', 'Diploma of Accounting', 'FNS50222', false, array['Must have completed FNSACC321, FNSACC322, FNSACC418 and FNSACC421 (e.g.', 'Accounting Principles Skill Set or Certificate IV in Accounting and Bookkeeping).', 'Year 12 LLN recommended.']::text[], 'https://www.tafensw.edu.au/course-areas/accounting-and-finance/courses/diploma-of-accounting--FNS50222-01'),
  ('BSB50620', 'TAFE NSW', 'NSW', 'Diploma of Marketing and Communication', 'BSB50620', false, array['One of: all core units of the Certificate IV in Marketing and Communication; significant industry experience (RPL for all core units); or two years'' full-time relevant work experience.', 'Year 12 LLN recommended.']::text[], 'https://tafensw.edu.au/course-areas/ABOR/courses/ABOR--BSB50620-01'),
  ('CUA50720', 'TAFE NSW', 'NSW', 'Diploma of Graphic Design', 'CUA50725', false, array['TAFE NSW now offers the Diploma of Graphic Design as CUA50725.', 'Certificate IV in Design (Graphic) or equivalent, or relevant skills/experience; plus a portfolio showing typography and graphic design software skills.', 'Head teacher may discuss your portfolio.']::text[], 'https://www.tafensw.edu.au/course-areas/art-and-design/courses/diploma-of-graphic-design--CUA50725-01'),
  ('CUA51020', 'TAFE NSW', 'NSW', 'Diploma of Screen and Media', 'CUA51020', false, array['No formal entry requirements.', 'Recommended: Certificate IV in Screen and Media or equivalent experience, Year 12 LLN, a computer that can run Adobe Creative Cloud.']::text[], 'https://www.tafensw.edu.au/course-areas/screen-media-and-games/courses/diploma-of-screen-and-media--CUA51020-01'),
  ('CUA50820', 'TAFE NSW', 'NSW', 'Diploma of Music', 'CUA50825', false, array['TAFE NSW now offers the Diploma of Music (Performance) as CUA50825.', 'Either Certificate III or IV in Music (Performance) or equivalent, or a pre-admission interview or audition.']::text[], 'https://www.tafensw.edu.au/course-areas/music-and-production/courses/diploma-of-music-performance--CUA50825-02'),
  ('SIS30321', 'TAFE NSW', 'NSW', 'Certificate III in Fitness', 'SIS30321', false, array['No entry requirements.', 'Recommended: at least 17 at enrolment (under 17s meet the head teacher), Year 10 LLN, able to perform CPR kneeling, confident in water.', 'Adult Pre-Exercise Screening at orientation.']::text[], 'https://www.tafensw.edu.au/course-areas/sport-and-recreation/courses/certificate-iii-in-fitness--SIS30321-01'),
  ('SIS40221', 'TAFE NSW', 'NSW', 'Certificate IV in Fitness', 'SIS40221', false, array['Must have completed Certificate III in Fitness or equivalent.', 'Year 12 LLN recommended.', 'Adult Pre-Exercise Screening at orientation.']::text[], 'https://www.tafensw.edu.au/course-areas/sport-and-recreation/courses/certificate-iv-in-fitness--SIS40221-01'),
  ('CPP41419', 'TAFE NSW', 'NSW', 'Certificate IV in Real Estate Practice', 'CPP41419', false, array['No entry requirements; Year 12-level literacy, numeracy and technical skills recommended.', 'Leads to applying for a Class 2 licence through NSW Fair Trading (new entrants first hold a certificate of registration).']::text[], 'https://www.tafensw.edu.au/course-areas/property-services/courses/certificate-iv-in-real-estate-practice--CPP41419-01'),
  ('AHC30921', 'TAFE NSW', 'NSW', 'Certificate III in Landscape Construction', 'AHC30921', true, array['Apprenticeship: employed as an apprentice; ACAP submits TPP.', 'Non-apprenticeship possible (check eligibility).', 'White card needed before entering a construction site.', 'Own PPE including steel-capped boots.']::text[], 'https://www.tafensw.edu.au/course-areas/horticulture/courses/certificate-iii-in-landscape-construction--AHC30921-01'),
  ('AHC50122', 'TAFE NSW', 'NSW', 'Diploma of Agriculture', 'AHC50122', false, array['Certificate III in Agriculture or equivalent, or 2 years'' experience in farming and agriculture.', 'LLN skills test with set minimum levels.']::text[], 'https://www.tafensw.edu.au/course-areas/farming-and-primary-production/courses/diploma-of-agriculture--AHC50122-01'),
  ('AHC51120', 'TAFE NSW', 'NSW', 'Diploma of Conservation and Ecosystem Management', 'AHC51120', false, array['No prior study required; LLN skills test with set minimum levels.', 'Recommended: Certificate III in Conservation and Land Management, relevant work or Landcare experience, or Year 12 with environmental knowledge.']::text[], 'https://www.tafensw.edu.au/course-areas/environment-and-sustainability/courses/diploma-of-conservation-and-ecosystem-management--AHC51120-01'),
  ('MSL40122', 'TAFE NSW', 'NSW', 'Certificate IV in Laboratory Techniques', 'MSL40122', false, array['No entry requirements.', 'Recommended: Year 10 LLN, comfort with basic maths, interest in science.']::text[], 'https://www.tafensw.edu.au/course-areas/laboratory-science/courses/certificate-iv-in-laboratory-techniques--MSL40122-01'),
  ('CPC50220', 'TAFE NSW', 'NSW', 'Diploma of Building and Construction (Building)', 'CPC50220', true, array['Certificate IV in Building and Construction (Building), or the 11 specified core units.', 'Valid white card.', 'LLN test before the first class.', 'Also offered as an apprenticeship/traineeship.', 'Counts towards (not all of) a NSW builder''s licence.']::text[], 'https://www.tafensw.edu.au/course-areas/building-and-construction-trades/courses/diploma-of-building-and-construction-building--CPC50220-01'),
  ('AVI50222', 'TAFE NSW', 'NSW', 'Diploma of Aviation (Commercial Pilot Licence – Aeroplane)', 'AVI50222', false, array['Offered with the Diploma of Aviation (Instrument Rating) as a dual diploma (TAFE NSW lists about $146,000 over 18 months).', 'Evidence of prior experience or study; current CASA Class 1 medical certificate; Aviation Reference Number; Aviation Security Identity Card; proof you''re over 18; LLN assessment at Level 4; a Flight Experience Package at extra cost.']::text[], 'https://tafensw.edu.au/course-areas/aviation-and-aircraft-maintenance/courses/aviation-and-aircraft-maintenance--AVI50222-01');
